function sheetConfig(spreadsheetId, tab) {
  if (
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    spreadsheetId.startsWith("YOUR_") ||
    !tab.trim()
  ) {
    throw new Error("Configure the spreadsheet ID and exact tab title.");
  }
  return { spreadsheetId, tab, range: "'" + tab.replace(/'/g, "''") + "'" };
}

const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  tab: "Queue",
};
return [{ json: { config: sheetConfig(settings.spreadsheetId, settings.tab) } }];

function a1Target(range) {
  if (typeof range !== "string") return null;
  const split = range.lastIndexOf("!");
  if (split < 1) return null;
  const tab = range.slice(0, split);
  return {
    tab: tab.startsWith("'") && tab.endsWith("'") ? tab.slice(1, -1).replace(/''/g, "'") : tab,
    cells: range
      .slice(split + 1)
      .replace(/\$/g, "")
      .toUpperCase(),
  };
}

function readTable(config, range, majorDimension, values) {
  const area =
    range === config.range || range === config.tab
      ? { tab: config.tab, cells: "A1" }
      : a1Target(range);
  if (
    area?.tab !== config.tab ||
    !/^A1(?::[A-Z]+\d+)?$/.test(area.cells) ||
    majorDimension !== "ROWS" ||
    !Array.isArray(values)
  ) {
    throw new Error("Google Sheets did not return the configured tab starting at A1.");
  }

  if (!values.length) return { candidates: [], marks: [], processedColumn: -1 };
  const [header, ...rows] = values;
  const idColumn = header.indexOf("ID");
  const processedColumn = header.indexOf("Processed");
  const namedHeadings = header.filter((value) => value !== "" && value !== null);
  if (
    idColumn < 0 ||
    processedColumn < 0 ||
    new Set(namedHeadings).size !== namedHeadings.length ||
    namedHeadings.some((value) => typeof value !== "string")
  ) {
    throw new Error("Use unique text headings including ID and Processed.");
  }

  const seen = new Set();
  const candidates = [];
  const marks = [];
  for (const [i, row] of rows.entries()) {
    const blank = (value) => value === null || value === undefined || value === "";
    if (row.every(blank)) continue;
    const rawId = row[idColumn];
    if (
      !(typeof rawId === "string" && rawId.trim() && !rawId.startsWith("=")) &&
      !Number.isSafeInteger(rawId)
    ) {
      throw new Error("Give each populated row a stable text or integer ID.");
    }
    const id = String(rawId);
    if (seen.has(id)) throw new Error("The sheet contains a duplicate ID.");
    seen.add(id);
    const pending = blank(row[processedColumn]);
    marks.push({ id, pending, row: i + 2 });
    if (pending)
      candidates.push({
        id,
        fields: Object.fromEntries(
          header.flatMap((name, column) => (name ? [[name, row[column] ?? null]] : [])),
        ),
      });
  }
  return { candidates, marks, processedColumn };
}

const source = $input.first().json;
const { candidates } = readTable(
  $("Choose the spreadsheet tab").first().json.config,
  source.range,
  source.majorDimension,
  source.values ?? [],
);
return candidates.length ? [{ json: { candidates } }] : [];

