function prepareMarks(config, candidates, completed, table, stamp) {
  const eligible = new Set(candidates.map((row) => row.id));
  if (
    !Array.isArray(completed) ||
    completed.some((id) => !eligible.has(id)) ||
    new Set(completed).size !== completed.length
  ) {
    throw new Error("The processing step must return each successful candidate ID at most once.");
  }

  const locations = new Map(table.marks.map((row) => [row.id, row]));
  let index = table.processedColumn + 1;
  let column = "";
  while (index > 0) {
    index--;
    column = String.fromCharCode(65 + (index % 26)) + column;
    index = Math.floor(index / 26);
  }
  const data = [];
  for (const id of completed) {
    const row = locations.get(id);
    if (!row) throw new Error("A completed ID disappeared before it could be marked.");
    if (row.pending) data.push({ range: config.range + "!" + column + row.row, values: [[stamp]] });
  }
  return data;
}

const source = $input.first().json,
  config = $("Choose the spreadsheet tab").first().json.config;
const table = readTable(config, source.range, source.majorDimension, source.values ?? []);
const batch = prepareMarks(
  config,
  $("Find unprocessed rows").first().json.candidates,
  $("Example processing step").first().json.completed,
  table,
  new Date().toISOString(),
);
return batch.length ? [{ json: { batch } }] : [];

