function confirmMarks(config, data, receipt) {
  if (
    receipt?.spreadsheetId !== config.spreadsheetId ||
    receipt.totalUpdatedCells !== data.length ||
    !Array.isArray(receipt.responses) ||
    receipt.responses.length !== data.length
  ) {
    throw new Error(
      "The sheet update was not confirmed. Review the Processed column before resuming.",
    );
  }
  for (let index = 0; index < data.length; index++) {
    const { range, values } = data[index];
    const response = receipt.responses[index];
    const expected = a1Target(range);
    const actual = a1Target(response?.updatedRange);
    if (
      actual?.tab !== expected.tab ||
      ![expected.cells, expected.cells + ":" + expected.cells].includes(actual.cells) ||
      response.updatedCells !== 1 ||
      JSON.stringify(response.updatedData?.values) !== JSON.stringify(values)
    ) {
      throw new Error("Google Sheets did not confirm the expected Processed cell and timestamp.");
    }
  }
}

const batch = $("Prepare Processed cell updates").first().json.batch;
confirmMarks($("Choose the spreadsheet tab").first().json.config, batch, $input.first().json);
return [{ json: { marked: batch.length } }];
